import{_ as s,a0 as p,w as l,s as d,ao as u,I as o,a1 as a,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何修复 ubuntu 中检测到系统程序错误的问题 | LCTT x X-CMD","titleTemplate":false,"description":"如何修复 ubuntu 中检测到系统程序错误的问题 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修复 ubuntu 中检测到系统程序错误的问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修复 ubuntu 中检测到系统程序错误的问题 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04","title":"如何修复 ubuntu 中检测到系统程序错误的问题","tag":"201507","desc":""},"relativePath":"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04.md","filePath":"[post].md"}'),i={name:"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04.md"};function b(m,t,h,f,g,T){const r=p("Link");return l(),d("div",null,[t[17]||(t[17]=u('<h1 id="如何修复-ubuntu-中检测到系统程序错误的问题" tabindex="-1">如何修复 ubuntu 中检测到系统程序错误的问题 <a class="header-anchor" href="#如何修复-ubuntu-中检测到系统程序错误的问题" aria-label="Permalink to “如何修复 ubuntu 中检测到系统程序错误的问题”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/system_program_Problem_detected.jpeg" alt=""></p><p>在过去的几个星期，（几乎）每次都有消息 <strong>Ubuntu 15.04在启动时检测到系统程序错误</strong> 跑出来“欢迎”我。那时我是直接忽略掉它的，但是这种情况到了某个时刻，它就让人觉得非常烦人了！</p><blockquote><p>检测到系统程序错误(System program problem detected)</p><p>你想立即报告这个问题吗？</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/System_Program_Problem_Detected.png" alt=""></p></blockquote><p>我肯定地知道如果你是一个Ubuntu用户，你可能曾经也遇到过这个恼人的弹窗。在本文中，我们将探讨在Ubuntu 14.04和15.04中遇到&quot;检测到系统程序错误(system program problem detected)&quot;时 应该怎么办。</p><h3 id="怎么解决ubuntu中-检测到系统程序错误-的错误" tabindex="-1">怎么解决Ubuntu中&quot;检测到系统程序错误&quot;的错误 <a class="header-anchor" href="#怎么解决ubuntu中-检测到系统程序错误-的错误" aria-label="Permalink to “怎么解决Ubuntu中检测到系统程序错误的错误”">​</a></h3><h4 id="那么这个通知到底是关于什么的" tabindex="-1">那么这个通知到底是关于什么的？ <a class="header-anchor" href="#那么这个通知到底是关于什么的" aria-label="Permalink to “那么这个通知到底是关于什么的？”">​</a></h4><p>大体上讲，它是在告知你，你的系统的一部分崩溃了。可别因为“崩溃”这个词而恐慌。这不是一个严重的问题，你的系统还是完完全全可用的。只是在之前的某个时刻某个程序崩溃了，而Ubuntu想让你决定要不要把这个问题报告给开发者，这样他们就能够修复这个问题。</p><h4 id="那么-我们点了-报告错误-的按钮后-它以后就不再显示了" tabindex="-1">那么，我们点了“报告错误”的按钮后，它以后就不再显示了？#### <a class="header-anchor" href="#那么-我们点了-报告错误-的按钮后-它以后就不再显示了" aria-label="Permalink to “那么，我们点了“报告错误”的按钮后，它以后就不再显示了？####”">​</a></h4><p>不，不是的！即使你点了“报告错误”按钮，最后你还是会被一个如下的弹窗再次“欢迎”一下：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Ubuntu_Internal_error.png" alt=""></p>',11)),o("p",null,[a(r,{href:"http://itsfoss.com/how-to-solve-sorry-ubuntu-12-04-has-experienced-an-internal-error/"},{default:n(()=>[...t[0]||(t[0]=[e("对不起，Ubuntu发生了一个内部错误",-1)])]),_:1}),t[2]||(t[2]=e("是个Apport（LCTT 译注：Apport是Ubuntu中错误信息的收集报告系统，详见Ubuntu Wiki中的Apport篇），它将会进一步的打开网页浏览器，然后你可以通过登录或创建",-1)),a(r,{href:"https://launchpad.net/"},{default:n(()=>[...t[1]||(t[1]=[e("Launchpad",-1)])]),_:1}),t[3]||(t[3]=e("帐户来填写一份漏洞（Bug)报告文件。你看，这是一个复杂的过程，它要花整整四步来完成。",-1))]),t[18]||(t[18]=u(`<h4 id="但是我想帮助开发者-让他们知道这个漏洞啊" tabindex="-1">但是我想帮助开发者，让他们知道这个漏洞啊 !#### <a class="header-anchor" href="#但是我想帮助开发者-让他们知道这个漏洞啊" aria-label="Permalink to “但是我想帮助开发者，让他们知道这个漏洞啊 !####”">​</a></h4><p>你这样想的确非常地周到体贴,而且这样做也是正确的。但是这样做的话，存在两个问题。第一，存在非常高的概率，这个漏洞已经被报告过了；第二，即使你报告了个这次崩溃，也无法保证你不会再看到它。</p><h4 id="那么-你的意思就是说别报告这次崩溃了" tabindex="-1">那么，你的意思就是说别报告这次崩溃了？#### <a class="header-anchor" href="#那么-你的意思就是说别报告这次崩溃了" aria-label="Permalink to “那么，你的意思就是说别报告这次崩溃了？####”">​</a></h4><p>对，也不对。如果你想的话，在你第一次看到它的时候报告它。你可以在上面图片显示的“显示细节（Show Details)”中，查看崩溃的程序。但是如果你总是看到它，或者你不想报告漏洞（Bug)，那么我建议你还是一次性摆脱这个问题吧。</p><h3 id="修复ubuntu中-检测到系统程序错误-的错误" tabindex="-1">修复Ubuntu中“检测到系统程序错误”的错误 <a class="header-anchor" href="#修复ubuntu中-检测到系统程序错误-的错误" aria-label="Permalink to “修复Ubuntu中“检测到系统程序错误”的错误”">​</a></h3><p>这些错误报告被存放在Ubuntu中目录/var/crash中。如果你翻看这个目录的话，应该可以看到有一些以crash结尾的文件。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Crash_reports_Ubuntu.jpeg" alt=""></p><p>我的建议是删除这些错误报告。打开一个终端，执行下面的命令：</p><pre><code>sudo rm /var/crash/*
</code></pre><p>这个操作会删除所有在/var/crash目录下的所有内容。这样你就不会再被这些报告以前程序错误的弹窗所扰。但是如果又有一个程序崩溃了，你就会再次看到“检测到系统程序错误”的错误。你可以再次删除这些报告文件，或者你可以禁用Apport来彻底地摆脱这个错误弹窗。</p><h4 id="彻底地摆脱ubuntu中的系统错误弹窗" tabindex="-1">彻底地摆脱Ubuntu中的系统错误弹窗 <a class="header-anchor" href="#彻底地摆脱ubuntu中的系统错误弹窗" aria-label="Permalink to “彻底地摆脱Ubuntu中的系统错误弹窗”">​</a></h4><p>如果你这样做，系统中任何程序崩溃时，系统都不会再通知你。如果你想问问我的看法的话，我会说，这不是一件坏事，除非你愿意填写错误报告。如果你不想填写错误报告，那么这些错误通知存不存在都不会有什么区别。</p><p>要禁止Apport，并且彻底地摆脱Ubuntu系统中的程序崩溃报告，打开一个终端，输入以下命令：</p><pre><code>gksu gedit /etc/default/apport
</code></pre><p>这个文件的内容是：</p><pre><code># 设置0表示禁用Apportw，或者1开启它。
# 你可以用下面的命令暂时关闭它：
# sudo service apport start force_start=1
enabled=1
</code></pre><p>把<strong>enabled=1</strong>改为<strong>enabled=0</strong>。保存并关闭文件。完成之后你就再也不会看到弹窗报告错误了。很显然，如果我们想重新开启错误报告功能，只要再打开这个文件，把enabled设置为1就可以了。</p><h4 id="你的有效吗" tabindex="-1">你的有效吗？ <a class="header-anchor" href="#你的有效吗" aria-label="Permalink to “你的有效吗？”">​</a></h4><p>我希望这篇教程能够帮助你修复Ubuntu 14.04和Ubuntu 15.04中检测到系统程序错误的问题。如果这个小窍门帮你摆脱了这个烦人的问题，请让我知道。</p><hr>`,20)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),a(r,{href:"http://itsfoss.com/how-to-fix-system-program-problem-detected-ubuntu/"},{default:n(()=>[...t[4]||(t[4]=[e("http://itsfoss.com/how-to-fix-system-program-problem-detected-ubuntu/",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("作者：",-1)),a(r,{href:"http://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[6]||(t[6]=[e("Abhishek",-1)])]),_:1}),t[10]||(t[10]=e(" 译者：",-1)),a(r,{href:"https://github.com/XLCYun"},{default:n(()=>[...t[7]||(t[7]=[e("XLCYun",-1)])]),_:1}),t[11]||(t[11]=e(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原创翻译，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...t[13]||(t[13]=[e("Linux中国",-1)])]),_:1}),t[16]||(t[16]=e(" 荣誉推出",-1))])])}const U=s(i,[["render",b]]);export{P as __pageData,U as default};
